    detailedTimeline: [moment('1176 d.C.', 'Nascimento', 'Nasce na linha Arden de Valoria.'), moment('1198 d.C.', 'Cheia dos Campos Baixos', 'Assume comando emergencial.'), moment('1204 d.C.', 'Crise sucessória', 'Mantém posição de herdeira sob pressão expansionista.')],
